CREATE INDEX IF NOT EXISTS idx_clips_oldest_order ON clips(
    (pinned_at IS NULL),
    pinned_at DESC,
    COALESCE(last_copied_at, captured_at) ASC,
    id ASC
);

CREATE INDEX IF NOT EXISTS idx_clips_alpha_order ON clips(
    (pinned_at IS NULL),
    pinned_at DESC,
    substr(content, 1, 64) ASC,
    id ASC
);
